static void config_json(const Config*c,Writer*w,int secret){put(w,"{");field(w,"url",c->url);put(w,",");field(w,"ca",c->ca);put(w,",");if(secret)field(w,"token",c->token);else put(w,c->token[0]?"\"has_token\":true":"\"has_token\":false");put(w,",\"pages\":[");for(unsigned i=0;i<c->count;++i){if(i)put(w,",");put(w,"{");field(w,"name",c->pages[i].name);put(w,",\"tiles\":[");for(unsigned j=0;j<c->pages[i].count;++j){Tile*t=(Tile*)&c->pages[i].tiles[j];if(j)put(w,",");put(w,"{");field(w,"id",t->id);put(w,",");field(w,"name",t->name);put(w,",");field(w,"icon",t->icon);put(w,"}");}put(w,"]}");}put(w,"]}");}
